enum class AxisInfo {
  unstructured,
  structured,
  scalarlike,
  scalar
};

bool PtrOffsetInfo::isStructured(int dim) const {
  return this->scalarLike || structured[dim] == AxisInfo::structured ||
         structured[dim] == AxisInfo::scalar;
}

bool PtrOffsetInfo::isStructured() const {
  return this->scalarLike || llvm::all_of(structured, [](auto dim) {
           return dim == AxisInfo::structured || dim == AxisInfo::scalar;
         });
}

bool PtrOffsetInfo::isUnstructured() const {
  return llvm::all_of(structured,
                      [](auto dim) { return dim == AxisInfo::unstructured; });
}

bool PtrOffsetInfo::isUnstructuredOrScalarlike() const {
  return llvm::all_of(structured, [](auto dim) {
    return dim == AxisInfo::unstructured || dim == AxisInfo::scalarlike ||
           dim == AxisInfo::scalar;
  });
}

PtrOffsetInfo combineInfo(const PtrOffsetInfo &lhs, const PtrOffsetInfo &rhs) {
  PtrOffsetInfo info;
  assert(lhs.getRank() == rhs.getRank() && "Rank must be same to be combined");

  info.setScalarLike(lhs.isScalarLike() && rhs.isScalarLike());
  auto &structuredRef = info.getStructuredRef();
  auto lhsStructured = lhs.getStructured();
  auto rhsStructured = rhs.getStructured();
  structuredRef.resize(lhs.getRank());
  for (size_t i = 0; i < structuredRef.size(); i++)
    structuredRef[i] = std::min(lhsStructured[i], rhsStructured[i]);
  return info;
}

void parseMulI(arith::MulIOp op, const Location &loc, RewriterBase &rewriter,
               llvm::DenseMap<Value, PtrOffsetInfo> &offsetMap) {
  // Get muli lhs
  auto lhs = op.getLhs();
  parse(lhs, op.getLoc(), rewriter, offsetMap);
  PtrOffsetInfo lhsOffsetInfo = offsetMap.at(lhs);
  auto &lhsStructured = lhsOffsetInfo.getStructuredRef();
  bool lhsScalarLike = lhsOffsetInfo.isScalarLike();
  // Get muli rhs
  auto rhs = op.getRhs();
  parse(rhs, op.getLoc(), rewriter, offsetMap);
  PtrOffsetInfo rhsOffsetInfo = offsetMap.at(rhs);
  auto &rhsStructured = rhsOffsetInfo.getStructuredRef();
  bool rhsScalarLike = rhsOffsetInfo.isScalarLike();
  // Set muli offset map
  size_t maxSize = std::max(lhsStructured.size(), rhsStructured.size());
  auto dst = op.getResult();
  offsetMap[dst] = PtrOffsetInfo();
  offsetMap[dst].setScalarLike(lhsScalarLike && rhsScalarLike);
  auto &dstStructured = offsetMap[dst].getStructuredRef();
  dstStructured.resize(maxSize);
  for (size_t i = 0; i < maxSize; i++)
    if (lhsScalarLike)
      dstStructured[i] = rhsStructured[i];
    else if (rhsScalarLike)
      dstStructured[i] = lhsStructured[i];
    else
      dstStructured[i] = PtrOffsetInfo::AxisInfo::unstructured;
}

void parseLoad(triton::LoadOp op, const Location &loc, RewriterBase &rewriter,
               llvm::DenseMap<Value, PtrOffsetInfo> &offsetMap) {
  // Get load ptr
  auto ptr = op.getPtr();
  parse(ptr, op.getLoc(), rewriter, offsetMap);
  // Set load offset map
  auto dst = op.getResult();
  offsetMap[dst] = PtrOffsetInfo();
  offsetMap[dst].setScalarLike(offsetMap[ptr].isScalarLike());
  auto tensorType = dyn_cast<RankedTensorType>(dst.getType());
  if (!tensorType)
    return;
  offsetMap[dst].setUnstructured(tensorType.getRank());
}

void parseMakeRange(triton::MakeRangeOp op, const Location &loc,
                    RewriterBase &rewriter,
                    llvm::DenseMap<Value, PtrOffsetInfo> &offsetMap) {
  // Set makeRange offset map
  auto dst = op.getResult();
  offsetMap[dst] = PtrOffsetInfo();
  offsetMap[dst].setStructured(1);
}

auto &dstStructured = dstOffsetInfo.getStructuredRef();
for (auto dim : dstType.getShape())
  dstStructured.push_back(dim == 1 ? PtrOffsetInfo::AxisInfo::scalar
                                   : PtrOffsetInfo::AxisInfo::scalarlike);
dstOffsetInfo.setScalarLike(true);
offsetMap[dst] = dstOffsetInfo;

if (!ptrType || op->hasAttr(ConverterUtils::discreteAttrName))
  return failure();
if (!offsetMap.contains(ptr))
  return op.emitError() << "PtrOffsetInfo should be computed\n" << ptr;

auto ptrOffsetInfo = offsetMap.at(ptr);

if (checkUnstructureAnnotated(op, rewriter))
  ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());

if (ptrOffsetInfo.isStructured() && !isDiscreteMask &&
    (!ptrOffsetInfo.isScalarLike() || llvm::all_of(ptrType.getShape(), [](int64_t dim) { return dim == 1; })))
    return failure();

for (int i = ptrOffsetInfo.getRank() - 1; i >= 0; i--) {
  if (!ptrOffsetInfo.isStructured(i))
    break;
  sizeInByte *= resultShape[i];
}

// Force scalarize if memory is not aligned
if (sizeInByte % 32 != 0)
  ptrOffsetInfo.setUnstructured(ptrOffsetInfo.getRank());

for (size_t i = 0; i < resultShape.size(); i++) {
  auto size = resultShape[i];
  auto structured = ptrOffsetInfo.getStructuredRef()[i] == PtrOffsetInfo::AxisInfo::structured;
  // handle indirect dimension
  strides.push_back(rewriter.getIndexAttr(1));
  Value sizeVal =
      rewriter.create<arith::ConstantOp>(loc, rewriter.getIndexAttr(size));
  if (structured) {
    offsets.push_back(rewriter.getIndexAttr(0));
    sizes.push_back(rewriter.getIndexAttr(size));
    extractedShape.push_back(size);
  } else {
    scf::ForOp forOp;
    if (auto mtptOp =
            srcPtr.template getDefiningOp<triton::MakeTensorPtrOp>()) {
      auto tptShape = mtptOp.getShape()[i];
      if (tptShape.getType() != rewriter.getIndexType()) {
        tptShape = rewriter.create<arith::IndexCastOp>(
            loc, rewriter.getIndexType(), tptShape);
      }
      sizeVal = rewriter.create<arith::MinSIOp>(loc, sizeVal, tptShape);
    }

    Value loopLower = zeroIdx;
    Value loopUpper = sizeVal;
    if (mstate && i < mstate->dims.size() && i < mstate->offsets.size()) {
      Value maskOffset = getValueOrCreateConstantIndexOp(
          rewriter, loc, mstate->offsets[i]);
      maskOffset = rewriter.create<arith::MaxSIOp>(loc, maskOffset, zeroIdx);
      maskOffset = rewriter.create<arith::MinSIOp>(loc, maskOffset, sizeVal);
      loopLower = maskOffset;

      Value maskDim = getValueOrCreateConstantIndexOp(
          rewriter, loc, mstate->dims[i]);
      maskDim = rewriter.create<arith::AddIOp>(loc, maskOffset, maskDim);
      maskDim = rewriter.create<arith::MinSIOp>(loc, maskDim, sizeVal);
      loopUpper = maskDim;
    }

    if (isLoadLike) {
      forOp = rewriter.create<scf::ForOp>(loc, loopLower, loopUpper, oneIdx,
                                          ValueRange({iterArg}));
      if (!newOpResult) {
        newOpResult = forOp->getResult(0);
      } else {
        rewriter.create<scf::YieldOp>(loc, forOp->getResult(0));
      }
      iterArg = forOp.getRegionIterArg(0);
    } else {
      forOp = rewriter.create<scf::ForOp>(loc, loopLower, loopUpper, oneIdx);
    }
    sizes.push_back(rewriter.getIndexAttr(1));
    offsets.push_back(forOp.getInductionVar());
    extractedShape.push_back(1);
    forOp->setAttr("ExtractedLoadOrStore",
                   UnitAttr::get(rewriter.getContext()));
    rewriter.setInsertionPointToStart(forOp.getBody());
  }
}

auto loc = op.getLoc();
SmallVector<OpFoldResult> idx(rank, rewriter.getIndexAttr(0));
auto extractedPtr = createExtractOp(loc, op.getPtr(), rewriter, idx);
Value mask = op.getMask();
Value other = op.getOther();
Value loadedValue = rewriter.create<triton::LoadOp>(
    loc, extractedPtr, /*mask=*/nullptr, /*other=*/nullptr,
    /*boundaryCheck=*/ArrayRef<int32_t>(),
    /*PaddingOptionAttr=*/nullptr);
loadedValue = rewriter.create<triton::SplatOp>(loc, op.getResult().getType(),
                                               loadedValue);
if (mask)
  rewriter.replaceOpWithNewOp<arith::SelectOp>(op, mask, loadedValue, other);
else
  rewriter.replaceOp(op, loadedValue);

bool fullyUnstructured = ptrOffsetInfo.isUnstructuredOrScalarlike();
auto extractedType = RankedTensorType::get(extractedShape, resultElementType);

Value extractedOffset;
if (fullyUnstructured) {
  if (auto mtptOp =
          srcPtr.template getDefiningOp<triton::MakeTensorPtrOp>()) {
    auto I64Type = rewriter.getIntegerType(64);
    srcPtr = mtptOp.getBase();
    extractedOffset = rewriter.create<arith::ConstantIntOp>(loc, 0, 64);
    for (auto [indVar, offset, stride] :
         llvm::zip_equal(offsets, ptrOffsetInfo.getOffsets(), mtptOp.getStrides())) {
      Value inductionVar = rewriter.create<arith::IndexCastOp>(
          loc, I64Type, cast<Value>(indVar));
      Value tptOffset = rewriter.create<arith::ExtSIOp>(loc, I64Type, offset);
      Value tptStride = rewriter.create<arith::ExtSIOp>(loc, I64Type, stride);
      tptOffset = rewriter.create<arith::MulIOp>(loc, tptStride, tptOffset);
      tptStride =
          rewriter.create<arith::MulIOp>(loc, tptStride, inductionVar);
      extractedOffset =
          rewriter.create<arith::AddIOp>(loc, extractedOffset, tptOffset);
      extractedOffset =
          rewriter.create<arith::AddIOp>(loc, extractedOffset, tptStride);
    }
  } else {
    extractedOffset = createExtractOp(loc, ptrOffset, rewriter, offsets);
  }
} else {
  extractedOffset =
      createExtractOp(loc, ptrOffset, rewriter, offsets, sizes, strides);
}

LLVM_DEBUG({
  auto &os = llvm::dbgs();
  os << "Extracted offset\n";
  os << extractedOffset << "\n";
});

assert(isa<triton::PointerType>(srcPtr.getType()) && "src must be ptr type");
if (!fullyUnstructured) {
  srcPtr = rewriter.create<triton::SplatOp>(
      loc, RankedTensorType::get(extractedShape, srcPtr.getType()), srcPtr);
}
Value ptrToAccess = rewriter.create<triton::AddPtrOp>(
    loc, srcPtr.getType(), srcPtr, extractedOffset);

